SourceCode.Declaration:
using XppInterpreter.Interpreter.Query;
using XppInterpreter.Interpreter;
using XppInterpreter;

/// <summary>
/// Class to generate a SyDa query from an Xpp AST during execution. 
/// Uses the visitor pattern.
/// </summary>
internal final class MXTXppQueryExpressionGenerator
{
    private RuntimeContext context;
    private Set tablesInQuery;
    private XppInterpreter.Interpreter.Query.QueryGenerationHelper generationHelper;
    private Common buffer;
    private boolean isExpression;

}

Method.Source:
/// <summary>
/// Constructor
/// </summary>
/// <param name = "_context">Runtime context</param>
/// <param name = "_tablesInQuery">Tables in query</param>
void new(RuntimeContext _context, Set _tablesInQuery, boolean _isExpression = false, Common _buffer = null)
{
    context = _context;
    tablesInQuery = _tablesInQuery;
    generationHelper = new XppInterpreter.Interpreter.Query.QueryGenerationHelper(_context);
    isExpression = _isExpression;
    buffer = _buffer;
}

public SysDaQueryExpression visitExpression(Parser.Expression _expression)
{
    if (_expression is Parser.TableField)
    {
        return this.visitTableField(_expression);
    }
    else if (_expression is Parser.BinaryOperation)
    {
        return this.visitBinaryOperation(_expression);
    }
    else if (_expression is Parser.UnaryOperation)
    {
        return this.visitUnaryOperation(_expression);
    }
    else if (_expression is Parser.Constant)
    {
        return this.visitConstant(_expression);
    }
    else if (_expression is Parser.Variable)
    {
        return this.visitVariable(_expression);
    }
    else if (!this.containsTableReference(_expression))
    {
        // Containers (the right side of "in"), ternaries, casts, and other
        // expressions that don't depend on a row can be computed once.
        return new SysDaValueExpression(generationHelper.ComputeExpression(_expression));
    }

    throw new System.Exception(strFmt("Query expression %1 contains a table-dependent construct that can't be translated to SysDa.", _expression.GetType().FullName));
}

private SysDaQueryExpression visitTableField(Parser.TableField _tableField)
{
    Common fieldBuffer = buffer;

    if (!fieldBuffer)
    {
        fieldBuffer = context.ScopeHandler.CurrentScope.GetVar(_tableField.TableName);
    }

    return new SysDaFieldExpression(fieldBuffer, _tableField.FieldName);
}

private SysDaQueryExpression visitBinaryOperation(Parser.BinaryOperation _binaryOperation)
{
    var left = this.visitExpression(_binaryOperation.LeftOperand);
    var right = this.visitExpression(_binaryOperation.RightOperand);

    switch (_binaryOperation.Token.TokenType)
    {
        case Lexer.TType::And: return new SysDaAndExpression(left, right);
        case Lexer.TType::Or: return new SysDaOrExpression(left, right);
        case Lexer.TType::Equal: return new SysDaEqualsExpression(left, right);
        case Lexer.TType::NotEqual: return new SysDaNotEqualsExpression(left, right);
        case Lexer.TType::Greater: return new SysDaGreaterThanExpression(left, right);
        case Lexer.TType::GreaterOrEqual: return new SysDaGreaterThanOrEqualsExpression(left, right);
        case Lexer.TType::Smaller: return new SysDaLessThanExpression(left, right);
        case Lexer.TType::SmallerOrEqual: return new SysDaLessThanOrEqualsExpression(left, right);
        case Lexer.TType::Plus: return new SysDaPlusExpression(left, right);
        case Lexer.TType::Minus: return new SysDaMinusExpression(left, right);
        case Lexer.TType::Division: return new SysDaDivideExpression(left, right);
        case Lexer.TType::Star: return new SysDaMultiplyExpression(left, right);
        case Lexer.TType::Mod: return new SysDaModExpression(left, right);
        case Lexer.TType::IntegerDivision: return new SysDaIntDivExpression(left, right);
        case Lexer.TType::In: return new SysDaInExpression(left, right);
        case Lexer.TType::Like: return new SysDaLikeExpression(left, right);
    }

    throw new System.Exception("Invalid binary expression.");
}

private SysDaQueryExpression visitUnaryOperation(Parser.UnaryOperation _unaryOperation)
{
    if (_unaryOperation.Token.TokenType == Lexer.TType::Negation)
    {
        return new SysDaNotExpression(this.visitExpression(_unaryOperation.Expression));
    }

    if (!this.containsTableReference(_unaryOperation))
    {
        return new SysDaValueExpression(generationHelper.ComputeExpression(_unaryOperation));
    }

    throw new System.Exception("This table-dependent unary expression can't be translated to SysDa.");
}

private SysDaQueryExpression visitVariable(Parser.Variable _variable)
{
    if (this.isVariableTable(_variable))
    {
        Common common = generationHelper.ComputeVariable(_variable.Caller);
        Lexer.Word word = _variable.Token;

        return new SysDaFieldExpression(common, word.Lexeme);
    }
    else if (_variable is Parser.FunctionCall)
    {
        if (this.containsTableReference(_variable))
        {
            throw new System.Exception("A query function call that depends on a table field can't be evaluated as a constant value.");
        }

        return new SysDaValueExpression(generationHelper.ComputeFunctionCall(_variable));
    }
    else
    {
        return new SysDaValueExpression(generationHelper.ComputeVariable(_variable));
    }
}

/// <summary>
/// Checks if the variable is a table buffer
/// </summary>
/// <param name = "_variable">Paser variable token</param>
/// <returns>If it references a table buffer, true, otherwise false</returns>
private boolean isVariableTable(Parser.Variable _variable)
{
    if (_variable.Caller != null && _variable.Caller.Token is Lexer.Word)
    {
        Lexer.Word word = _variable.Caller.Token;

        return tablesInQuery.in(word.Lexeme);
    }

    return false;
}

/// <summary>
/// Determines row dependence using the buffers in this concrete query. A
/// qualified CLR/application member can therefore still be evaluated once,
/// while a member on any joined table remains a SysDa field expression.
/// </summary>
private boolean containsTableReference(Parser.Expression _expression)
{
    if (_expression == null)
    {
        return false;
    }

    if (_expression is Parser.TableField)
    {
        return true;
    }

    if (_expression is Parser.BinaryOperation)
    {
        Parser.BinaryOperation binary = _expression;
        return this.containsTableReference(binary.LeftOperand) ||
               this.containsTableReference(binary.RightOperand);
    }

    if (_expression is Parser.UnaryOperation)
    {
        Parser.UnaryOperation unary = _expression;
        return this.containsTableReference(unary.Expression);
    }

    if (_expression is Parser.Ternary)
    {
        Parser.Ternary ternary = _expression;
        return this.containsTableReference(ternary.Condition) ||
               this.containsTableReference(ternary.Left) ||
               this.containsTableReference(ternary.Right);
    }

    if (_expression is Parser.ContainerInitialisation)
    {
        Parser.ContainerInitialisation containerExpression = _expression;
        System.Object[] containerElements = containerExpression.Elements.ToArray();
        for (int elementIndex = 0; elementIndex < containerElements.Length; elementIndex++)
        {
            if (this.containsTableReference(containerElements.GetValue(elementIndex)))
            {
                return true;
            }
        }

        return false;
    }

    if (_expression is Parser.Is)
    {
        Parser.Is typeTestExpression = _expression;
        return this.containsTableReference(typeTestExpression.Expression);
    }

    if (_expression is Parser.As)
    {
        Parser.As asExpression = _expression;
        return this.containsTableReference(asExpression.Expression);
    }

    if (_expression is Parser.Variable)
    {
        Parser.Variable variable = _expression;
        if (this.isVariableTable(variable))
        {
            return true;
        }

        if (variable.Caller != null && this.containsTableReference(variable.Caller))
        {
            return true;
        }

        if (_expression is Parser.ArrayAccess)
        {
            Parser.ArrayAccess arrayAccess = _expression;
            if (this.containsTableReference(arrayAccess.Index))
            {
                return true;
            }
        }

        if (_expression is Parser.FunctionCall)
        {
            Parser.FunctionCall functionCall = _expression;
            var parameters = functionCall.Parameters.ToArray();
            for (int parameterIndex = 0; parameterIndex < parameters.Length; parameterIndex++)
            {
                if (this.containsTableReference(parameters.GetValue(parameterIndex)))
                {
                    return true;
                }
            }
        }
    }

    return false;
}
